INSERT INTO `lqbk_posts` VALUES (50039,1,'2024-03-27 04:17:32','2024-03-27 04:17:32','<h1>About Us</h1>				\n								<figure><img src=\"http://localhost:8080/wp-content/uploads/2025/01/ACHC_HIT_exp-01-08-2026_rotated.pdf-1.jpeg\" alt=\"ACHC_HIT_exp-01-08-2026_rotated.pdf\" /></figure><figure><img src=\"http://localhost:8080/wp-content/uploads/2025/02/mmla_lic.png\" alt=\"mmla_lic\" /></figure>			\n						<svg aria-hidden=\"true\" viewBox=\"0 0 1000 1000\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M646 125C629 125 613 133 604 142L308 442C296 454 292 471 292 487 292 504 296 521 308 533L604 854C617 867 629 875 646 875 663 875 679 871 692 858 704 846 713 829 713 812 713 796 708 779 692 767L438 487 692 225C700 217 708 204 708 187 708 171 704 154 692 142 675 129 663 125 646 125Z\"></path></svg>					\n						<svg aria-hidden=\"true\" viewBox=\"0 0 1000 1000\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M696 533C708 521 713 504 713 487 713 471 708 454 696 446L400 146C388 133 375 125 354 125 338 125 325 129 313 142 300 154 292 171 292 187 292 204 296 221 308 233L563 492 304 771C292 783 288 800 288 817 288 833 296 850 308 863 321 871 338 875 354 875 371 875 388 867 400 854L696 533Z\"></path></svg>					\n					<h2>Our Certification &amp; Credibility</h2>				\n		<p>MMLA offers home health, infusion, and research services. We are a staff of Skilled Nursing Clinicians that base our success on our patients\' long-term good health.</p><p>We believe in personalized care based on your health concerns.</p><p>To schedule an appointment,<br> please call: <a href=\"tel:(213) 545- MMLA (6652)\" target=\"_blank\" rel=\"noopener\"><strong>(213) 545- MMLA (6652)</strong></a></p>		\n					<a href=\"https://www.youtube.com/watch?v=IJkc_FEi-fM\" target=\"_blank\">\n									ACHC Accreditation!\n					</a>\n															<img width=\"1920\" height=\"1080\" src=\"http://localhost:8080/wp-content/uploads/2024/03/5D-1.png\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2024/03/5D-1.png 1920w, http://localhost:8080/wp-content/uploads/2024/03/5D-1-300x169.png 300w, http://localhost:8080/wp-content/uploads/2024/03/5D-1-1024x576.png 1024w, http://localhost:8080/wp-content/uploads/2024/03/5D-1-768x432.png 768w, http://localhost:8080/wp-content/uploads/2024/03/5D-1-1536x864.png 1536w\" sizes=\"(max-width: 1920px) 100vw, 1920px\" />															\n					<h2>Our Mission</h2>				\n		<p>We are committed to advancing the practice of home infusion nursing through continuous education, innovation, and adherence to the highest standards of safety and care. Our goal is to empower patients to live more independently and joyfully, minimizing the disruption to their lives and fostering a positive healing environment. The heart of our mission lies in our belief that everyone deserves access to quality healthcare services that respect their dignity, preferences, and unique needs.</p>		\n					<a href=\"tel:(213)%20545-MMLA\" target=\"_blank\">\n									Schedule Appointment\n					</a>\n					<h2>Our Vision</h2>				\n		<p>We envision a future where every individual requiring infusion therapy can access top-tier, personalized nursing care in the sanctuary of their own home, surrounded by the comfort and support of their loved ones. Our aim is to extend our reach, ensuring that no patient is left behind due to geographical, physical, or socioeconomic barriers.</p>		\n															<img width=\"1920\" height=\"1080\" src=\"http://localhost:8080/wp-content/uploads/2024/03/6E.jpg\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2024/03/6E.jpg 1920w, http://localhost:8080/wp-content/uploads/2024/03/6E-300x169.jpg 300w, http://localhost:8080/wp-content/uploads/2024/03/6E-1024x576.jpg 1024w, http://localhost:8080/wp-content/uploads/2024/03/6E-768x432.jpg 768w, http://localhost:8080/wp-content/uploads/2024/03/6E-1536x864.jpg 1536w\" sizes=\"(max-width: 1920px) 100vw, 1920px\" />															\n					<h1>Call to Action: (213) 545-6652</h1>				\n					<a href=\"#\">\n									Schedule a Consultation\n					</a>\n					<a href=\"http://localhost:8080/refer-a-patient/\">\n									Refer a Patient\n					</a>','About Us','','publish','closed','closed','','about-us','','','2025-12-11 17:33:11','2025-12-11 10:33:11','',0,'https://mobilemedicalla.com/?page_id=39',0,'page','',0),(50041,1,'2024-03-27 04:17:50','2024-03-27 04:17:50','<h1>Our Services</h1>				\n															<img width=\"1000\" height=\"667\" src=\"http://localhost:8080/wp-content/uploads/2024/03/9f7f86eec3.jpeg\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2024/03/9f7f86eec3.jpeg 1000w, http://localhost:8080/wp-content/uploads/2024/03/9f7f86eec3-300x200.jpeg 300w, http://localhost:8080/wp-content/uploads/2024/03/9f7f86eec3-768x512.jpeg 768w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" />															\n					<h2>Home Health Services</h2>				\n		<p>We provide a range of clinical and support services for patients in the comfort of their home. Home health care is more convenient, less expensive, and just as effective as the care received in the hospital or a nursing home. Our clinical team of highly trained nurses, therapists and other providers work with the patient, their family, and their physician on a personalized treatment plan. Based on the patient\'s needs, we provide specialty services, as well as care coordination, patient education on self-management, health promotion and disease prevention, medications, and lifestyle modifications for optimal wellness</p>		\n					<h2>HIT Services</h2>				\n		<p>We provide a range of clinical and support services for patients in the comfort of their home. Home health care is more convenient, less expensive, and just as effective as the care received in the hospital or a nursing home. Our clinical team of highly trained nurses, therapists and other providers work with the patient, their family, and their physician on a personalized treatment plan. Based on the patient\'s needs, we provide specialty services, as well as care coordination, patient education on self-management, health promotion and disease prevention, medications, and lifestyle modifications for optimal wellness</p>		\n															<svg viewBox=\"0 0 192 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M0 384.662V127.338c0-17.818 21.543-26.741 34.142-14.142l128.662 128.662c7.81 7.81 7.81 20.474 0 28.284L34.142 398.804C21.543 411.404 0 402.48 0 384.662z\"></path></svg>\n								<svg viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M288.662 352H31.338c-17.818 0-26.741-21.543-14.142-34.142l128.662-128.662c7.81-7.81 20.474-7.81 28.284 0l128.662 128.662c12.6 12.599 3.676 34.142-14.142 34.142z\"></path></svg>\n												<a tabindex=\"0\">More Information</a>\n					<p>Mobile Medical LA works with major pharmacies to increase the quality of patient care and reduce hospital stays and readmissions. We offer flexible contracts to meet the needs of every patient, physician, and healthcare network. Our services include but are not limited to:</p><ul><li>Total Parental Nutrition (TPN)</li><li>Antibiotics</li><li>Pain Management</li><li>Immunoglobulin (IVIG)</li><li>Hydration</li><li>Antiemetic</li><li>Antiviral Therapy</li><li>Antifungal Therapy</li><li>Injectables</li></ul>\n					<a href=\"https://mobilemedicalla.com/#1\">\n									ACHC certified for HIT\n					</a>\n															<img width=\"1920\" height=\"1080\" src=\"http://localhost:8080/wp-content/uploads/2024/03/7D.jpg\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2024/03/7D.jpg 1920w, http://localhost:8080/wp-content/uploads/2024/03/7D-300x169.jpg 300w, http://localhost:8080/wp-content/uploads/2024/03/7D-1024x576.jpg 1024w, http://localhost:8080/wp-content/uploads/2024/03/7D-768x432.jpg 768w, http://localhost:8080/wp-content/uploads/2024/03/7D-1536x864.jpg 1536w\" sizes=\"(max-width: 1920px) 100vw, 1920px\" />															\n															<img width=\"1920\" height=\"1080\" src=\"http://localhost:8080/wp-content/uploads/2024/03/8F.jpg\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2024/03/8F.jpg 1920w, http://localhost:8080/wp-content/uploads/2024/03/8F-300x169.jpg 300w, http://localhost:8080/wp-content/uploads/2024/03/8F-1024x576.jpg 1024w, http://localhost:8080/wp-content/uploads/2024/03/8F-768x432.jpg 768w, http://localhost:8080/wp-content/uploads/2024/03/8F-1536x864.jpg 1536w\" sizes=\"(max-width: 1920px) 100vw, 1920px\" />															\n					<h2>Clinical Trials support services</h2>				\n		<p>MMLA clinical research staff will coordinate and oversee the homecare nursing services from its corporate office located in Inglewood, California. MMLA will ensure the proper provision of services in accordance with the protocol, study contract and applicable regulations. A Home care Manager (Study Manager) will be assigned to the project in the U.S/Canada. MMLA complies with all applicable GCP and ICH guidelines and regulations, HIPAA and applicable federal, state and local regulations.</p>		\n															<svg viewBox=\"0 0 192 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M0 384.662V127.338c0-17.818 21.543-26.741 34.142-14.142l128.662 128.662c7.81 7.81 7.81 20.474 0 28.284L34.142 398.804C21.543 411.404 0 402.48 0 384.662z\"></path></svg>\n								<svg viewBox=\"0 0 320 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M288.662 352H31.338c-17.818 0-26.741-21.543-14.142-34.142l128.662-128.662c7.81-7.81 20.474-7.81 28.284 0l128.662 128.662c12.6 12.599 3.676 34.142-14.142 34.142z\"></path></svg>\n												<a tabindex=\"0\">More Information</a>\n					<p>The Study Manager will ensure adequate training of all involved homecare study staff and will oversee study-related activities, timelines, adherence to budget, and quality assurance checks. MMLA will prepare a study-specific homecare training manual including study synopsis, clinician and nursing requirements, documentation, billing information and template of Physician Order Form.</p><p>The Study Manager will handle day-to-day interactions with the home care study personnel, the Sponsor /Investigator Site or Institution and their representatives. The Study Manager will provide status reports to the as mutually agreed upon (approximately weekly). MMLA will consolidate billings from each of the participating home care personel and will submit invoices to the Sponsor/Institution on a monthly basis. The Study Manager will be available 24/7 to respond to any issues arising during the course of the study.</p>\n					<h1>Call to Action: (213) 545-6652</h1>				\n					<a href=\"#\">\n									Schedule a Consultation\n					</a>\n					<a href=\"http://localhost:8080/refer-a-patient/\">\n									Refer a Patient\n					</a>','Our Services','','publish','closed','closed','','our-services','','','2025-12-11 17:31:23','2025-12-11 10:31:23','',0,'https://mobilemedicalla.com/?page_id=41',0,'page','',0),(50766,1,'2024-04-01 21:04:57','2024-04-01 21:04:57','<style>/*! elementor - v3.20.0 - 26-03-2024 */\n.elementor-heading-title{padding:0;margin:0;line-height:1}.elementor-widget-heading .elementor-heading-title[class*=elementor-size-]>a{color:inherit;font-size:inherit;line-height:inherit}.elementor-widget-heading .elementor-heading-title.elementor-size-small{font-size:15px}.elementor-widget-heading .elementor-heading-title.elementor-size-medium{font-size:19px}.elementor-widget-heading .elementor-heading-title.elementor-size-large{font-size:29px}.elementor-widget-heading .elementor-heading-title.elementor-size-xl{font-size:39px}.elementor-widget-heading .elementor-heading-title.elementor-size-xxl{font-size:59px}</style><h2>Your Account Has been Successfully Validated</h2>		\n			<h2><a href=\"https://mobilemedicalla.com/rns-portal/\">Login</a></h2>','Confirmation','','publish','closed','closed','','confirmation','','','2024-04-10 20:35:32','2024-04-10 20:35:32','',0,'https://mobilemedicalla.com/?page_id=766',0,'page','',0),(50820,1,'2024-04-03 23:13:32','2024-04-03 23:13:32','[client-portal]','Dashboard','','publish','closed','closed','','dashboard','','','2024-04-06 22:59:41','2024-04-06 22:59:41','',0,'https://mobilemedicalla.com/?page_id=820',0,'page','',0),(50915,1,'2024-04-06 20:51:38','2024-04-06 20:51:38','[wpforms id=\"913\"]','Password Reset','','publish','closed','closed','','password-reset','','','2024-04-06 21:03:30','2024-04-06 21:03:30','',0,'https://mobilemedicalla.com/?page_id=915',0,'page','',0),(51103,1,'2025-01-27 10:27:24','2025-01-27 10:27:24','','Portal','','publish','closed','closed','','portal','','','2025-01-29 10:14:36','2025-01-29 10:14:36','',0,'https://mobilemedicalla.com/?page_id=1103',0,'page','',0),(51115,1,'2025-01-27 23:11:14','2025-01-27 23:11:14','<h1>IVIG News</h1>','IVIG News','','publish','closed','closed','','ivig-news','','','2025-12-11 17:34:37','2025-12-11 10:34:37','',0,'https://mobilemedicalla.com/?page_id=1115',0,'page','',0),(51234,1,'2025-03-31 11:26:23','2025-03-31 11:26:23','<h1>Where Complex Therapies Meet Compassionate Home Care</h1>				\n					<h3>Providing personalized home infusion services and research-ready nursing support across California</h3>				\n					<h2>About Mobile Medical LA</h2>				\n		<p>Founded in 2017 in the heart of Los Angeles, <strong>Mobile Medical LA</strong> is a vision of expert home health nurses who saw the growing need for <strong>in-home care tailored to patients with complex neurological, immunological, and oncological conditions.</strong> They understood that patients deserved more than basic home health visits—they deserved skilled care delivered with compassion and consistency.</p><p>The name “<strong>Mobile Medical LA</strong>” reflects the company’s mission: bringing high-quality clinical care to the patient, wherever they are. Over time we expanded our services across Southern California, specializing in managing long-term home infusions and supporting patients participating in clinical research.</p><p>We are proud to be <strong>both home health certified and home infusion treatment (HIT) certified</strong> — a distinction that sets us apart in the industry. Being <strong>home health certified</strong> means we meet stringent state and federal standards for providing skilled nursing and therapeutic services in the home setting. Our <em><strong>HIT certification</strong></em> confirms that we are qualified to safely administer complex medications, including biologics and immunoglobulins, with protocols that ensure patient safety and optimal outcomes.</p>		\n					<h2>Specialized in IVIG Infusion Therapy</h2>				\n					<h2>Pioneers in Clinical Research at Home</h2>				\n		<p>Our nurses are specially trained to <strong>administer intravenous immunoglobulin (IVIG) treatments</strong> safely in the home—a complex therapy that requires clinical precision, experience, and a deep understanding of autoimmune and neurological conditions. We recognized early on that IVIG administration isn’t one-size-fits-all, and our approach ensures <strong>every treatment is individualized, closely monitored, and supportive</strong> of long-term health.</p><p>To maintain the highest standards of care, our <strong>nurses receive additional, ongoing training and certifications</strong> through the Immunoglobulin National Society (IGNS) and other professional organizations. This ensures that every clinician on our team is current with the latest protocols, safety standards, and patient care practices specific to IVIG.</p>		\n															<img width=\"640\" height=\"480\" src=\"http://localhost:8080/wp-content/uploads/2025/04/ivig_info_graphic.webp\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2025/04/ivig_info_graphic.webp 640w, http://localhost:8080/wp-content/uploads/2025/04/ivig_info_graphic-300x225.webp 300w\" sizes=\"(max-width: 640px) 100vw, 640px\" />															\n															<img width=\"1200\" height=\"628\" src=\"http://localhost:8080/wp-content/uploads/2025/04/Home-based-Clinical-Trials.jpg\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2025/04/Home-based-Clinical-Trials.jpg 1200w, http://localhost:8080/wp-content/uploads/2025/04/Home-based-Clinical-Trials-300x157.jpg 300w, http://localhost:8080/wp-content/uploads/2025/04/Home-based-Clinical-Trials-1024x536.jpg 1024w, http://localhost:8080/wp-content/uploads/2025/04/Home-based-Clinical-Trials-768x402.jpg 768w\" sizes=\"(max-width: 1200px) 100vw, 1200px\" />															\n		<p>New drug therapies — such as IVIG and other biologics — are developed for highly specialized populations, often requiring precise administration methods. Mobile Medical LA plays a vital role in helping patients access these cutting-edge treatments by facilitating clinical trial participation. Our deep expertise in complex IVIG infusions directly informs our ability to execute clinical trial protocols with accuracy and care, ensuring continuity between investigational research and safe, effective home treatment.</p><p dir=\"ltr\">We partner with <strong>principal investigators, contract research organizations (CROs), and the pharmaceutical industry</strong> to deliver investigational drugs directly in the patient’s home. Our nurses are trained in <strong>following clinical trial protocols and regulatory compliance,</strong> allowing research sponsors to conduct reliable studies in a patient’s home—without compromising data integrity or patient safety.</p><p dir=\"ltr\">We believe that bringing research to the home isn’t just about convenience—it’s about expanding access, improving retention, and making breakthroughs possible.</p>		\n					<h2>Why Patients &amp; Providers Trust Us</h2>				\n							<ul>\n							<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M173.898 439.404l-166.4-166.4c-9.997-9.997-9.997-26.206 0-36.204l36.203-36.204c9.997-9.998 26.207-9.998 36.204 0L192 312.69 432.095 72.596c9.997-9.997 26.207-9.997 36.204 0l36.203 36.204c9.997 9.997 9.997 26.206 0 36.204l-294.4 294.401c-9.998 9.997-26.207 9.997-36.204-.001z\"></path></svg>						\n										Specialized in Complex Care – Experts in IVIG, biologics, and clinical research nursing\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M173.898 439.404l-166.4-166.4c-9.997-9.997-9.997-26.206 0-36.204l36.203-36.204c9.997-9.998 26.207-9.998 36.204 0L192 312.69 432.095 72.596c9.997-9.997 26.207-9.997 36.204 0l36.203 36.204c9.997 9.997 9.997 26.206 0 36.204l-294.4 294.401c-9.998 9.997-26.207 9.997-36.204-.001z\"></path></svg>						\n										Compliant – Home health and infusion certified, fully licensed, and HIPAA-compliant\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M173.898 439.404l-166.4-166.4c-9.997-9.997-9.997-26.206 0-36.204l36.203-36.204c9.997-9.998 26.207-9.998 36.204 0L192 312.69 432.095 72.596c9.997-9.997 26.207-9.997 36.204 0l36.203 36.204c9.997 9.997 9.997 26.206 0 36.204l-294.4 294.401c-9.998 9.997-26.207 9.997-36.204-.001z\"></path></svg>						\n										Compassion Meets Clinical Precision – Every visit combines advanced training with personalized attention\n									</li>\n								<li>\n							<svg aria-hidden=\"true\" viewBox=\"0 0 512 512\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M173.898 439.404l-166.4-166.4c-9.997-9.997-9.997-26.206 0-36.204l36.203-36.204c9.997-9.998 26.207-9.998 36.204 0L192 312.69 432.095 72.596c9.997-9.997 26.207-9.997 36.204 0l36.203 36.204c9.997 9.997 9.997 26.206 0 36.204l-294.4 294.401c-9.998 9.997-26.207 9.997-36.204-.001z\"></path></svg>						\n										Serving All of Southern California – Deep community roots with fast, reliable in-home care coverage\n									</li>\n						</ul>\n															<img width=\"1024\" height=\"683\" src=\"http://localhost:8080/wp-content/uploads/2025/04/preparing-for-injection-1024x683.jpg\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2025/04/preparing-for-injection-1024x683.jpg 1024w, http://localhost:8080/wp-content/uploads/2025/04/preparing-for-injection-300x200.jpg 300w, http://localhost:8080/wp-content/uploads/2025/04/preparing-for-injection-768x512.jpg 768w, http://localhost:8080/wp-content/uploads/2025/04/preparing-for-injection-1536x1024.jpg 1536w, http://localhost:8080/wp-content/uploads/2025/04/preparing-for-injection-2048x1365.jpg 2048w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />															\n															<img width=\"780\" height=\"470\" src=\"http://localhost:8080/wp-content/uploads/2025/04/HIT_Subcutaneous_780x470.jpg\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2025/04/HIT_Subcutaneous_780x470.jpg 780w, http://localhost:8080/wp-content/uploads/2025/04/HIT_Subcutaneous_780x470-300x181.jpg 300w, http://localhost:8080/wp-content/uploads/2025/04/HIT_Subcutaneous_780x470-768x463.jpg 768w\" sizes=\"(max-width: 780px) 100vw, 780px\" />															\n															<img width=\"1024\" height=\"576\" src=\"http://localhost:8080/wp-content/uploads/2025/04/hizentra-1024x576.jpg\" alt=\"\" srcset=\"http://localhost:8080/wp-content/uploads/2025/04/hizentra-1024x576.jpg 1024w, http://localhost:8080/wp-content/uploads/2025/04/hizentra-300x169.jpg 300w, http://localhost:8080/wp-content/uploads/2025/04/hizentra-768x432.jpg 768w, http://localhost:8080/wp-content/uploads/2025/04/hizentra.jpg 1280w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" />															\n					<h1>Call to Action: (213) 545-6652</h1>				\n					<a href=\"#\">\n									Schedule a Consultation\n					</a>\n					<a href=\"http://localhost:8080/refer-a-patient/\">\n									Refer a Patient\n					</a>','Home','','publish','closed','closed','','home','','','2025-12-17 07:35:51','2025-12-17 00:35:51','',0,'https://mobilemedicalla.com/new-home/',0,'page','',0),(51492,1,'2025-04-24 11:03:15','2025-04-24 11:03:15','<h1>Refer a Patient Form</h1>		<form id=\"wpforms-form-1479\" data-formid=\"1479\" me